  `proy_email` varchar(120) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Email del proyecto',
  `proy_estado` tinyint(0) NOT NULL DEFAULT 1 COMMENT '1 activo, 0 inactivo',
